-- Renew the Deal of the Week online promotion for 26 October – 1 November 2026 (Asia/Dhaka).
-- Carries forward the 12 verified catalogue products whose current prices, MRPs,
-- and stock levels remain valid and unchanged.

-- 1. Deactivate prior current campaigns
update public.storefront_item_promotions
set is_current = false
where is_current is true;

-- 2. Insert week two promotions
